"use strict";
// A terminal helper whose JSDoc says widths are numbers; off a TTY they
// are undefined (the shape of commander's HelpContext.helpWidth).

class Terminal {
  constructor(tty) {
    this.tty = tty;
    this.settings = {
      columns: () => (this.tty ? 80 : undefined),
    };
  }

  /**
   * @returns {number}
   */
  columns() {
    return this.settings.columns();
  }

  /**
   * @typedef OutputContext
   * @type {object}
   * @property {boolean} error
   * @property {number} width
   *
   * @param {boolean} error
   * @returns {OutputContext}
   */
  outputContext(error) {
    const width = this.settings.columns();
    return { error, width };
  }

  /**
   * @param {OutputContext} context
   * @returns {string}
   */
  describe(context) {
    return `width ${context.width}${context.error ? " (stderr)" : ""}`;
  }
}

module.exports = { Terminal };
